public class Main {
  static class Student {
    String name;
    int score;

    Student(String name, int score) {
      this.name = name;
      this.score = score;
    }

    String level() {
      if (score >= 90) return "A";
      if (score >= 80) return "B";
      return "C";
    }
  }

  public static void main(String[] args) {
    Student student = new Student("Ada", 95);
    System.out.println(student.name + " -> " + student.level());
  }
}
